1	import { captureException, getSentryIfAvailable } from "../sentry/internal";
2	import { unsubscribeSetup } from "./live-common-setup";
3	import { setEnvUnsafe } from "@ledgerhq/live-env";
4	import { serializeError } from "@ledgerhq/errors";
5	import { log } from "@ledgerhq/logs";
6	import sentry, { setTags } from "~/sentry/internal";
7	import {
8	  transportClose,
9	  transportExchange,
10	  transportExchangeBulk,
11	  transportExchangeBulkUnsubscribe,
12	  transportListen,
13	  transportListenUnsubscribe,
14	  transportOpen,
15	} from "~/internal/transportHandler";
16	import {
17	  transportCloseChannel,
18	  transportExchangeBulkChannel,
19	  transportExchangeBulkUnsubscribeChannel,
20	  transportExchangeChannel,
21	  transportListenChannel,
22	  transportListenUnsubscribeChannel,
23	  transportOpenChannel,
24	} from "~/config/transportChannels";
25	import { Message } from "./types";
26	process.on("exit", () => {
27	  console.debug("exiting process, unsubscribing all...");
28	  unsubscribeSetup();
29	  getSentryIfAvailable()?.close(2000);
30	});
31	process.title = "Ledger Live Internal";
32	process.on("uncaughtException", err => {
33	  process.send &&
34	    process.send({
35	      type: "uncaughtException",
36	      error: serializeError(err),
37	    });
38	  // FIXME we should ideally do this:
39	  // process.exit(1)
40	  // but for now, until we kill all exceptions:
41	  console.error(err, "uncaughtException");
42	  captureException(err);
43	});
44	
45	// eslint-disable-next-line no-unused-vars
46	let sentryEnabled = process.env.INITIAL_SENTRY_ENABLED !== "false";
47	const userId = process.env.SENTRY_USER_ID || "";
48	sentry(() => Boolean(userId) && sentryEnabled, userId);
49	const { INITIAL_SENTRY_TAGS } = process.env;
50	if (INITIAL_SENTRY_TAGS) {
51	  const parsed = JSON.parse(INITIAL_SENTRY_TAGS);
52	  if (parsed) setTags(parsed);
53	}
54	
55	process.on("message", (m: Message) => {
56	  switch (m.type) {
57	    case transportOpenChannel:
58	      transportOpen(m);
59	      break;
60	    case transportExchangeChannel:
61	      transportExchange(m);
62	      break;
63	    case transportExchangeBulkChannel:
64	      transportExchangeBulk(m);
65	      break;
66	    case transportExchangeBulkUnsubscribeChannel:
67	      transportExchangeBulkUnsubscribe(m);
68	      break;
69	    case transportListenChannel:
70	      transportListen(m);
71	      break;
72	    case transportListenUnsubscribeChannel:
73	      transportListenUnsubscribe(m);
74	      break;
75	    case transportCloseChannel:
76	      transportClose(m);
77	      break;
78	    case "sentryLogsChanged": {
79	      const { payload } = m;
80	      sentryEnabled = payload;
81	      break;
82	    }
83	    case "set-sentry-tags": {
84	      setTags(JSON.parse(m.tagsJSON));
85	      break;
86	    }
87	    case "internalCrashTest": {
88	      captureException(new Error("CrashTestInternal"));
89	      break;
90	    }
91	    case "setEnv": {
92	      const { name, value } = m.env;
93	      setEnvUnsafe(name, value);
94	      break;
95	    }
96	    default:
97	      log("error", `internal thread: '${(m as { type: string }).type}' event not supported`);
98	  }
99	});
100	process.on("disconnect", () => {
101	  process.exit(0);
102	});
103	log("internal", "Internal process is up!");
