1	import { ipcRenderer } from "electron";
2	import Transport from "@ledgerhq/hw-transport";
3	import { log } from "@ledgerhq/logs";
4	import { deserializeError } from "@ledgerhq/errors";
5	import { v4 as uuidv4 } from "uuid";
6	import {
7	  transportCloseChannel,
8	  transportListenChannel,
9	  transportListenUnsubscribeChannel,
10	  transportExchangeBulkChannel,
11	  transportExchangeBulkUnsubscribeChannel,
12	  transportExchangeChannel,
13	  transportOpenChannel,
14	} from "~/config/transportChannels";
15	import { Observer } from "rxjs";
16	import { DescriptorEvent } from "@ledgerhq/types-devices";
17	
18	const rendererRequest = (channel: string, data: unknown) => {
19	  return new Promise((resolve, reject) => {
20	    const requestId = uuidv4();
21	    const replyChannel = `${channel}_RESPONSE_${requestId}`;
22	    const handler = (
23	      _event: Electron.IpcRendererEvent,
24	      message: { error?: unknown; data: unknown },
25	    ) => {
26	      if (message.error) {
27	        reject(deserializeError(message.error));
28	      } else {
29	        resolve(message.data);
30	      }
31	      ipcRenderer.removeListener(replyChannel, handler);
32	    };
33	    ipcRenderer.on(replyChannel, handler);
34	    ipcRenderer.send(channel, {
35	      data,
36	      requestId,
37	    });
38	  });
39	};
40	export class IPCTransport extends Transport {
41	  static isSupported = (): Promise<boolean> => Promise.resolve(typeof ipcRenderer === "function");
42	  // this transport is not discoverable
43	  static list = (): Promise<unknown[]> => Promise.resolve([]);
44	  static listen = (observer: Observer<DescriptorEvent<string>>) => {
45	    const requestId = uuidv4();
46	    const replyChannel = `${transportListenChannel}_RESPONSE_${requestId}`;
47	    const handler = (
48	      _event: Electron.IpcRendererEvent,
49	      message: { error?: unknown; data: DescriptorEvent<string> },
50	    ) => {
51	      if (message.error) {
52	        observer.error(deserializeError(message.error));
53	      } else {
54	        const { data } = message;
55	        if (data) {
56	          observer.next(data);
57	        } else {
58	          observer.complete();
59	        }
60	      }
61	    };
62	    ipcRenderer.on(replyChannel, handler);
63	    ipcRenderer.send(transportListenChannel, {
64	      requestId,
65	    });
66	    return {
67	      unsubscribe: () => {
68	        ipcRenderer.removeListener(replyChannel, handler);
69	        ipcRenderer.send(transportListenUnsubscribeChannel, {
70	          requestId,
71	        });
72	      },
73	    };
74	  };
75	
76	  static async open(id: string): Promise<Transport> {
77	    await rendererRequest(transportOpenChannel, {
78	      descriptor: id,
79	    });
80	    return new IPCTransport(id);
81	  }
82	
83	  id: string;
84	  constructor(id: string) {
85	    super();
86	    this.id = id;
87	  }
88	
89	  async exchange(apdu: Buffer): Promise<Buffer> {
90	    const apduHex = apdu.toString("hex");
91	    log("ipc-apdu", "=> " + apduHex);
92	    const responseHex = await rendererRequest(transportExchangeChannel, {
93	      descriptor: this.id,
94	      apduHex,
95	    });
96	    log("ipc-apdu", "<= " + responseHex);
97	    return Buffer.from(responseHex as string, "hex");
98	  }
99	
100	  exchangeBulk(apdus: Buffer[], observer: Observer<Buffer>) {
101	    const apdusHex = apdus.map(apdu => apdu.toString("hex"));
102	    log("ipc-apdu-info", "bulk of " + apdusHex.length + " apdus");
103	    const requestId = uuidv4();
104	    const replyChannel = `${transportExchangeBulkChannel}_RESPONSE_${requestId}`;
105	    const handler = (
106	      _event: Electron.IpcRendererEvent,
107	      message: { error?: unknown; data: unknown },
108	    ) => {
109	      if (message.error) {
110	        observer.error(deserializeError(message.error));
111	      } else {
112	        const { data } = message;
113	        if (data) {
114	          observer.next(Buffer.from(data as string, "hex"));
115	        } else {
116	          observer.complete();
117	        }
118	      }
119	    };
120	    ipcRenderer.on(replyChannel, handler);
121	    ipcRenderer.send(transportExchangeBulkChannel, {
122	      data: {
123	        descriptor: this.id,
124	        apdusHex,
125	      },
126	      requestId,
127	    });
128	    return {
129	      unsubscribe: () => {
130	        ipcRenderer.removeListener(replyChannel, handler);
131	        ipcRenderer.send(transportExchangeBulkUnsubscribeChannel, {
132	          data: {
133	            descriptor: this.id,
134	          },
135	          requestId,
136	        });
137	      },
138	    };
139	  }
140	
141	  setScrambleKey() {
142	    // empty fn
143	  }
144	
145	  close(): Promise<void> {
146	    return rendererRequest(transportCloseChannel, {
147	      descriptor: this.id,
148	    }).then(() => {
149	      /* close() must return a Promise<void> */
150	    });
151	  }
