// Subscribes to a transport handler observable and forwards each structured
// response to the main process. `multi` streams additionally emit a final
// "complete" message (no data/error) so the main process can close the channel.
const forwardTransport = (
  channel: string,
  requestId: string,
  observable: import("rxjs").Observable<{ type?: string; data?: unknown; error?: unknown }>,
  { multi }: { multi: boolean },
) => {
  const subscription = observable.subscribe({
    next: response => {
      if (response.error) {
        process.send?.({ type: channel, error: response.error, requestId });
      } else {
        process.send?.({ type: channel, data: response.data, requestId });
      }
    },
    complete: () => {
      if (multi) {
        process.send?.({ type: channel, requestId });
      }
      transportSubscriptions.delete(requestId);
    },
  });
  transportSubscriptions.set(requestId, subscription);
};

